		const format_info* info_of(bb::rhi::format format)
		{
			for (const format_info& info : format_infos) {
				if (info.neutral == format) {
					return &info;
				}
			}
			return nullptr;
		}

		bool is_srgb(bb::rhi::format f)
		{
			return (f == bb::rhi::format::rgba8_srgb) || (f == bb::rhi::format::bc1_srgb) || (f == bb::rhi::format::bc2_srgb) || (f == bb::rhi::format::bc3_srgb) || (f == bb::rhi::format::bc7_srgb);
		}

