		// What a HRESULT that is not good does: a device that is gone is noted (the graphics are made again where a frame begins), anything else ends the program.
		void check(HRESULT result, const char* what)
		{
			if (result >= 0) {
				return;
			}
			bool lost = (int32_t(result) == hr_removed) || (int32_t(result) == hr_hung) || (int32_t(result) == hr_reset);
			if (lost && recovery_enabled()) {
				note_device_loss(int32_t(result), what);
				return;
			}
			char buffer[256];
			if (lost) {
				snprintf(buffer, sizeof(buffer), "the graphics device was lost (%s in %s) and making the graphics again is turned off.", bb::rhi::native_result_name(int32_t(result)), what);
			} else {
				snprintf(buffer, sizeof(buffer), "%s failed (HRESULT 0x%08X).", what, unsigned(result));
			}
			fail(buffer);
		}

		uint64_t fnv1a(const void* data, size_t size)
		{
			uint64_t       hash  = 0xCBF29CE484222325ull;
			const uint8_t* bytes = static_cast<const uint8_t*>(data);
			for (size_t i = 0; i < size; i++) {
				hash = (hash ^ bytes[i]) * 0x100000001B3ull;
			}
			return hash;
		}

		UINT subresource(uint32_t mip, uint32_t layer, uint32_t mips)
		{
			return D3D11CalcSubresource(mip, layer, mips);
		}
